        detector = ArucoPatchDetector(str(REFERENCE_CHECKER_8X10_PATH), self.debug_mode, self.output_dir)
        source_patches, _ = detector.detect_patches(photo_of_checker)
        self.debug_paths.update(detector.debug_paths)

        if not source_patches or len(source_patches) != 75:
            print(f"[ERROR] Aruco patch detection failed. Found {len(source_patches)} patches, expected 75.")
            return {"corrected_image": None, "debug_paths": self.debug_paths}

        if self.debug_mode: print("[INFO] Step 2: Calculating average colors of detected patches...")
        color_space = "hsv" if correction_method == "hsv" else "bgr"
        source_colors = self._calculate_average_colors(source_patches, color_space)
        self._visualize_average_colors(source_patches, source_colors, "source_aruco_8x10")

        if self.debug_mode: print("[INFO] Step 3: Using pre-loaded reference colors.")
        if color_space == "hsv":
            ref_colors_hsv = [cv2.cvtColor(np.uint8([[bgr]]), cv2.COLOR_BGR2HSV)[0][0] for bgr in self.reference_colors_bgr]
            ref_colors = ref_colors_hsv
        else:
            ref_colors = self.reference_colors_bgr

        aligned_source_colors = source_colors
        aligned_ref_colors = ref_colors

        if len(aligned_source_colors) < 6:
            print(f"[ERROR] Not enough valid patch pairs found ({len(aligned_source_colors)}). Need at least 6.")
            return {"corrected_image": None, "debug_paths": self.debug_paths}

        if self.debug_mode: print(f"[INFO] Step 4: Calculating '{correction_method}' correction model...")
        corrector = ColorCorrector()
        correction_model = corrector.calculate_correction_model(aligned_source_colors, aligned_ref_colors, method=correction_method)

        if self.debug_mode: print("[INFO] Step 5: Applying correction to main image...")
        corrected_image = corrector.apply_correction_model(image_to_correct, correction_model, method=correction_method)
        self._save_debug_image("final_corrected_image_aruco_8x10", corrected_image)

        if self.debug_mode: print("--- ArUco 8x10 Color Correction Pipeline Finished ---\n")
        return {"corrected_image": corrected_image, "correction_model": correction_model, "debug_paths": self.debug_paths}

