def run_patch_detection_on_image(self, image: np.ndarray) -> Dict:
    """
    Runs only the patch detection stage on a given image for validation purposes.
    This method is aware of the checker type and uses the appropriate detector.
    """
    if image is None or image.size == 0:
        return {"patches": [], "patch_coords": [], "detection_method": "error"}

    if self.checker_type == "aruco_8x10":
        if self.debug_mode:
            print("[INFO] GUI Validation: Running patch detection with ArucoPatchDetector.")

        # Use the correct reference path for the detector
        detector = ArucoPatchDetector(str(REFERENCE_CHECKER_8X10_PATH), self.debug_mode, self.output_dir)
        patches, coords = detector.detect_patches(image)
        self.debug_paths.update(detector.debug_paths) # Collect debug paths
        detection_method = "aruco_8x10"
    else:
        # Use the pipeline's internal multi-stage detection method for legacy checkers.
        if self.debug_mode:
            print("[INFO] GUI Validation: Running patch detection with legacy _detect_patches_from_image.")
        patches, coords = self._detect_patches_from_image(image, "validation")
        detection_method = "multi-stage"

    if not patches:
        detection_method = "failed"

    return {"patches": patches, "patch_coords": coords, "detection_method": detection_method}
